from functools import lru_cache
mask={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# observed orientations: color2 missing TL: [[0,1],[1,1]]; color3 missing BL: [[1,1],[0,1]]; color4 missing TR: [[1,0],[1,1]]
tiles=[]
# square
for r in range(3):
 for c in range(5):
  cells={(r+i,c+j) for i in range(2) for j in range(2)}
  if cells<=mask: tiles.append((cells,1,'square'))
orient=[({(0,1),(1,0),(1,1)},2,'missing TL'),({(0,0),(0,1),(1,1)},3,'missing BL'),({(0,0),(1,0),(1,1)},4,'missing TR')]
for r in range(3):
 for c in range(5):
  for coords,col,name in orient:
   cells={(r+i,c+j) for i,j in coords}
   if cells<=mask: tiles.append((cells,col,name))
@lru_cache(None)
def solve(rem, sq):
 rem=set(rem)
 if not rem: return [()] if sq==1 else []
 p=min(rem)
 sols=[]
 for cells,col,name in tiles:
  if p in cells and cells<=rem and (col!=1 or sq==0):
   for rest in solve(tuple(sorted(rem-cells)),sq+(col==1)):
    sols.append(((col,tuple(sorted(cells)),name),)+rest)
 return sols
for num_sq in range(5):
 # use separate recursion target count
 @lru_cache(None)
 def f(rem,sq):
  rem=set(rem)
  if not rem: return [()] if sq==num_sq else []
  p=min(rem); out=[]
  for cells,col,name in tiles:
   if p in cells and cells<=rem and sq+(col==1)<=num_sq:
    for rest in f(tuple(sorted(rem-cells)),sq+(col==1)):
     out.append(((col,tuple(sorted(cells)),name),)+rest)
  return out
 sols=f(tuple(sorted(mask)),0)
 print('squares',num_sq,'solutions',len(sols))
 if sols:
  for t in sols[:5]: print(t)
